SET LOCAL search_path = app, pg_catalog;

-- Product identities and listing details from Shopee Database/new_clothes_sample_full.csv.
CREATE TABLE clothes_image_database (
    item_id TEXT PRIMARY KEY NOT NULL,
    shop_id TEXT NOT NULL,
    search_group TEXT NOT NULL,
    search_term TEXT NOT NULL,
    name TEXT NOT NULL,
    url TEXT NOT NULL,
    image_url TEXT NOT NULL,
    price INTEGER NOT NULL CHECK (price >= 0),
    currency TEXT NOT NULL
);

ALTER TABLE shopping_suggestions ADD COLUMN catalog_item_id TEXT REFERENCES clothes_image_database(item_id);
CREATE UNIQUE INDEX one_catalog_suggestion_per_look ON shopping_suggestions(saved_look_id)
    WHERE catalog_item_id IS NOT NULL;
GRANT SELECT ON clothes_image_database TO mbti_closet_runtime;















































